uint32_t ReadRice(WaveScanDecodeState* state) {
    uint32_t quotient = 0;
    if (state->num_bits <= 16) {
      state->bits |= static_cast<uint32_t>(state->data[0]) << state->num_bits;
      state->bits |=
          static_cast<uint32_t>(state->data[1]) << (state->num_bits + 8);
      state->data += 2;
      state->num_bits += 16;
    }
    while (true) {
      if (!state->bits) {
        quotient += state->num_bits;
        state->num_bits = 16;
        state->bits = static_cast<uint32_t>(state->data[0]) |
            (static_cast<uint32_t>(state->data[1]) << 8);
        state->data += 2;
        continue;
      }
      const uint32_t zeroes = __builtin_ctz(state->bits);
      quotient += zeroes;
      const uint32_t consumed = zeroes + 1;
      state->bits = consumed == 32 ? 0 : state->bits >> consumed;
      state->num_bits -= consumed;
      break;
    }
    const uint32_t parameter = state->rice_parameter;
    if (!parameter) {
      return quotient;
    }
    if (state->num_bits < parameter) {
      state->bits |=
          static_cast<uint32_t>(state->data[0]) << state->num_bits;
      state->bits |=
          static_cast<uint32_t>(state->data[1]) << (state->num_bits + 8);
      state->data += 2;
      state->num_bits += 16;
    }
    const uint32_t remainder = state->bits & ((1 << parameter) - 1);
    state->bits >>= parameter;
    state->num_bits -= parameter;
    return (quotient << parameter) | remainder;
}

void StartWaveDecoder(
    uint8_t wave,
    uint8_t* destination,
    WaveScanDecodeState* state) {
  state->data = kWaveResiduals + kWaveOffsets[wave];
  state->destination = destination;
  state->bits = 0;
  state->num_bits = 0;
  state->sample = kWaveFirstSamples[wave];
  state->difference = 0;
  state->target = wave;
  state->index = 1;
  state->rice_parameter = kWaveRiceParameters[wave];
  destination[0] = static_cast<uint8_t>(state->sample);
}

bool AdvanceWaveDecoder(WaveScanDecodeState* state, size_t count) {
  size_t end = state->index + count;
  if (end > kWaveScanWaveSize) {
    end = kWaveScanWaveSize;
  }
  while (state->index < end) {
    const uint32_t zigzag = ReadRice(state);
    const int32_t residual = static_cast<int32_t>(zigzag >> 1) ^
        -static_cast<int32_t>(zigzag & 1);
    state->difference += residual;
    state->sample += state->difference;
    state->destination[state->index++] =
        static_cast<uint8_t>(state->sample);
  }
  return state->index == kWaveScanWaveSize;
}

void DecodeWave(uint8_t wave, uint8_t* destination) {
  WaveScanDecodeState state;
  StartWaveDecoder(wave, destination, &state);
  AdvanceWaveDecoder(&state, kWaveScanWaveSize - 1);
}

